html:
{#- Termo de Responsabilidade — acknowledgment signed by the guard (not a sanction).
    Logo = Empresa Padrão's Company logo; local + footer code from SIGOS Settings. -#}
{%- set empresa = frappe.db.get_single_value("SIGOS Settings", "empresa_padrao") or frappe.db.get_single_value("Global Defaults", "default_company") -%}
{%- set logo = frappe.db.get_value("Company", empresa, "company_logo") if empresa else None -%}
{%- set codigo = frappe.db.get_single_value("SIGOS Settings", "codigo_formulario_termo") or "" -%}
{%- set local = frappe.db.get_single_value("SIGOS Settings", "local_documentos") or doc.delegacao or "" -%}
{%- set jurista = frappe.db.get_value("User", doc.jurista, "full_name") if doc.jurista else "" -%}
{%- set meses = ["Janeiro", "Fevereiro", "Março", "Abril", "Maio", "Junho", "Julho", "Agosto", "Setembro", "Outubro", "Novembro", "Dezembro"] -%}
{%- set d = frappe.utils.getdate(doc.data) if doc.data else None -%}
{%- set dc = frappe.utils.getdate(doc.data_ocorrencia) if doc.data_ocorrencia else None -%}
<style>
	@page { size: A4 portrait; margin: 14mm 18mm; }
	.tr { font-family: "Times New Roman", Times, serif; color: #111; font-size: 12.5px; }
	.tr * { box-sizing: border-box; }
	.tr-logo { height: 62px; margin-bottom: 18px; }
	.tr-logo img { max-height: 62px; max-width: 170px; }
	.tr-title { border-top: 1px solid #333; border-bottom: 1px solid #333; text-align: center;
		font-size: 16px; letter-spacing: .08em; padding: 10px 0; margin-bottom: 20px; }
	.tr-title small { display: block; font-size: 9px; color: #666; letter-spacing: 0; margin-top: 2px; }
	.tr-tb { width: 100%; border-collapse: collapse; margin-bottom: 18px; }
	.tr-tb td { border: 1px solid #333; padding: 4px 7px; height: 22px; }
	.tr-k { text-transform: uppercase; font-size: 10.5px; white-space: nowrap; width: 1%; }
	.tr-v { font-family: "Courier New", Courier, monospace; font-size: 12px; font-weight: bold; }
	.tr-txt { line-height: 1.75; text-align: justify; white-space: pre-line; min-height: 220px; }
	.tr-obs { margin-top: 10px; font-size: 11px; }
	.tr-local { text-align: right; margin: 30px 0 46px; }
	.tr-sig { width: 100%; border-collapse: collapse; }
	.tr-sig td { width: 50%; text-align: center; vertical-align: top; padding: 0 18px; font-size: 11px; }
	.tr-sig .ln { border-top: 1px solid #333; margin-bottom: 4px; }
	.tr-sig .nm { font-family: "Courier New", Courier, monospace; font-size: 11px; display: block; margin-top: 2px; }
	.tr-foot { margin-top: 60px; font-size: 9.5px; }
	.tr-foot .own { text-align: center; font-style: italic; margin-bottom: 12px; }
	.tr-foot .cod { font-family: Arial, Helvetica, sans-serif; font-size: 10.5px; line-height: 15px; white-space: pre-line; }
	.tr-ref { font-size: 8.5px; color: #777; text-align: right; margin-top: 4px; }
</style>
<div class="tr">
	<div class="tr-logo">{% if logo %}<img src="{{ logo }}">{% endif %}</div>
	<div class="tr-title">TERMO DE RESPONSABILIDADE{% if doc.docstatus == 0 %}<small>RASCUNHO — não submetido</small>{% elif doc.docstatus == 2 %}<small>CANCELADO</small>{% endif %}</div>

	<table class="tr-tb">
		<tr><td class="tr-k">Nome</td><td class="tr-v" colspan="3" style="text-transform:uppercase">{{ doc.nome_do_vigilante or doc.vigilante or "" }}</td></tr>
		<tr><td class="tr-k">Número</td><td class="tr-v">{{ doc.mecanografico or "" }}</td>
			<td class="tr-k">Categoria</td><td class="tr-v">{{ doc.categoria or "" }}</td></tr>
		<tr><td class="tr-k">Posto</td><td class="tr-v">{{ frappe.db.get_value("Posto De Vigilancia", doc.posto, "nome_do_posto") or doc.posto if doc.posto else "" }}</td>
			<td class="tr-k">{{ "Processo" if doc.processo_disciplinar else "Participação" }}</td><td class="tr-v">{{ doc.processo_disciplinar or doc.participacao or "" }}{% if dc %} · {{ dc.strftime("%d.%m.%Y") }}{% endif %}</td></tr>
		<tr><td class="tr-k">Infracções</td><td class="tr-v" colspan="3">{{ doc.infracoes or "" }}</td></tr>
	</table>

	<div class="tr-txt">{{ doc.declaracao or "" }}</div>
	{%- if doc.observacoes %}<div class="tr-obs"><b>Observações:</b> {{ doc.observacoes }}</div>{% endif %}

	<div class="tr-local">{{ local or "____________" }}, aos {{ "%02d" | format(d.day) if d else "____" }} de {{ meses[d.month - 1] if d else "______________" }} de {{ d.year if d else "20__" }}</div>

	<table class="tr-sig"><tr>
		<td><div class="ln"></div>O Vigilante<span class="nm">{{ doc.nome_do_vigilante or "" }}</span></td>
		<td><div class="ln"></div>O Jurista<span class="nm">{{ jurista or "" }}</span></td>
	</tr></table>

	<div class="tr-foot">
		{%- if empresa %}<div class="own">Este documento é propriedade da {{ empresa | upper }}. Não é permitida sua reprodução sem autorização.</div>{% endif %}
		{%- if codigo %}<div class="cod">{{ codigo | e }}</div>{% endif %}
		<div class="tr-ref">{{ doc.name }}</div>
	</div>
</div>
